local addonName, WC = ...

-- Getrich recipe data. GENERATED by tools/gen_data.py on 2026-10-22 -- do not edit by hand.
-- WoW Forever client build 1.60.1.70450 (DB2 tables from wago.tools): SkillLineAbility (skill line, thresholds,
--   NumSkillUps, AcquireMethod), SpellReagents, SpellEffect (24 create item: EffectBasePointsF +- Variance/2;
--   36 learn spell), SpellName, ItemEffect + ItemXItemEffect + ItemSparse (recipe items).
-- WC.RECIPES[skillLine][recipeID] (recipeID = spell ID, as C_TradeSkillUI uses):
--   s learn skill (orange from s), y yellow, g grey (green from floor((y + g) / 2)), o output item (nil for
--   enchants), n1-n2 yield per craft (both omitted when 1), r = { itemID, qty, itemID, qty, ... },
--   ab = SkillLineAbility ID, su = skill-ups per craft (omitted = 1).
--   t = "i" taught by the recipe item ri (s = the item's required skill),
--       "t" learned with the profession (a = 1: AcquireMethod 1, s exact, nothing to train) or from a
--           trainer (s estimated, se = 1),
--       "?" no source in this build: its recipe item ri has no ItemSparse row (dropped or not released yet),
--           or no item and no known trainer (quest rewards, Season of Discovery spells); s estimated.
--   se = 1: s is a guess. The client has no trainer requirements, so s = y (yellow): Classic trainers taught
--       439 of 440 checked recipes at or below their Classic yellow (median 20 points below). Forever moved
--       many yellows and some requirements (Bronze Warhammer was made at 110 in Forever, yellow 155).
--   s can be above y when a recipe item asks more skill than Forever's lowered yellow (the recipe is yellow
--       or green when learned); y == g happens (no yellow/green phase).
-- Left out: retired recipes (AcquireMethod 3, spells without a name), ranks/abilities without reagents or
--   output, recipes whose product has no ItemSparse row in this build (218: unreleased or removed items),
--   learn skill > 300. Recipe items flagged deprecated or missing from ItemSparse teach nothing.
-- Contents: Poisons 24, First Aid 32, Blacksmithing 415, Leatherworking 462, Alchemy 177, Herbalism 3, Cooking 129, Mining 16, Tailoring 401, Engineering 246, Enchanting 236, Fishing 3, Skinning 3.

WC.SKILLUP = {
  formula = "classic",
  source = "https://wowinterface.com/downloads/info9529-TradeskillAdvice.html",
  note = "orange (skill < y) 1; yellow/green (y <= skill < g) (g - skill) / (g - y); grey (skill >= g) 0. Empirical (TradeskillAdvice: 'rate = (current skill-grey) / (yellow-grey)'); its averages over the yellow and green halves, 75% and 25%, are the vmangos server defaults (SkillChance.Yellow/Green).",
}

-- Storage: each skill line is a string (one recipe per line) decoded into the tables above the first time
